#!/bin/bash
# Random init dataset for the GL optimisation with Re, Ru replaced by V, Sc (TiNbZrHfTaMoWYVSc): 1800 compositions
# listed in slurm/compositions/TiNbZrHfTaMoWYVSc_gl.csv, same design as the final TiNbZrHfTaMoWYReRu database
# (1000 full simplex, seeds 6000..6999; 100 faces for every k = 9 ... 2, seeds (70+k)*1000 + i, fractions >= 0.05;
# generated by scripts/composition_list.py, see slurm/README.md).  Full pipeline in GL (gg + lloyd, consts.py).
# Default 60 tasks x 30 interleaved rows, 6 concurrent (5 rounds, ~1-1.5 days per task): with the opt runs holding
# cpus only ~28 tasks fit under the 512-cpu cap at once, the rest stay PENDING and start when cpus free up.
#   slurm/submit_random_gl_TiNbZrHfTaMoWYVSc.sh
#   env DRYRUN=1 slurm/submit_random_gl_TiNbZrHfTaMoWYVSc.sh          plan only (tcsh: env VAR=x cmd)
#   env FILE=slurm/compositions/TiNbZrHfTaMoWYVSc_gl.missing.csv NTASKS=10 slurm/submit_random_gl_TiNbZrHfTaMoWYVSc.sh
FILE=${FILE:-slurm/compositions/TiNbZrHfTaMoWYVSc_gl.csv}
WORKDIR=${WORKDIR:-random.ratios/sra.TiNbZrHfTaMoWYVSc.kp10.ew0.6.gl}
NTASKS=${NTASKS:-60}; CONCURRENT=${CONCURRENT:-6}; JOBNAME=rnd10vsc
# run directly on the login node (it calls sbatch itself); under sbatch $0 is a spool copy without submit_complist.sh
[ -n "${SLURM_JOB_ID:-}" ] && { echo "this submit script calls sbatch itself: run it on the login node WITHOUT sbatch, e.g.  slurm/submit_random_gl_TiNbZrHfTaMoWYVSc.sh"; exit 2; }
source "$(dirname "$0")/submit_complist.sh"
